const STORAGE_KEY='antifitna-matches-v2';
let matches=JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]');
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const fmt=n=>Number(n).toLocaleString('fr-FR');
const dateLabel=d=>new Date(`${d}T12:00:00`).toLocaleDateString('fr-FR',{day:'2-digit',month:'short',year:'numeric'});
function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(matches));}
function showView(view){$$('[data-view]').forEach(el=>el.hidden=el.dataset.view!==view);$$('[data-view-link]').forEach(el=>el.classList.toggle('active',el.dataset.viewLink===view));window.scrollTo({top:0,behavior:'smooth'});}
function render(){
  const cedric=matches.filter(m=>m.winner==='Cédric').length, issa=matches.filter(m=>m.winner==='Issa').length;
  const games=[...new Set(matches.map(m=>m.game))]; const best=matches.slice().sort((a,b)=>b.score-a.score)[0];
  $('#gamesStat').textContent=matches.length;$('#matchCount').textContent=`${matches.length} ${matches.length===1?'partie':'parties'}`;$('#cedricWins').textContent=`${cedric} ${cedric===1?'win':'wins'}`;$('#issaWins').textContent=`${issa} ${issa===1?'win':'wins'}`;$('#balanceStat').textContent=matches.length?`${cedric} — ${issa}`:'—';$('#highStat').textContent=best?fmt(best.score):'—';$('#highGame').textContent=best?best.game:'aucune partie';$('#gamesPlayedStat').textContent=games.length;$('#cedricBar').style.width=matches.length?`${cedric/matches.length*100}%`:'50%';
  const rank=[['Cédric',cedric,'a1'],['Issa',issa,'a2']].sort((a,b)=>b[1]-a[1]);$('#ranking').innerHTML=matches.length?rank.map((r,i)=>`<div class="rank"><div class="avatar ${r[2]}">${r[0][0]}</div><div class="rank-info"><div class="rank-name">${i+1}. ${r[0]}</div><div class="rank-meta">${r[1]} victoire${r[1]>1?'s':''}</div></div><strong class="rank-score">${r[1]}</strong></div>`).join(''):'<div class="empty-state">Le classement apparaîtra ici.</div>';
  renderChart();renderGames(games);renderHistory();$('#knownGames').innerHTML=games.map(g=>`<option value="${g}">`).join('');
}
function renderChart(){const empty=$('#chartEmpty'),chart=$('#chart');if(!matches.length){empty.hidden=false;chart.hidden=true;return}empty.hidden=true;chart.hidden=false;const recent=matches.slice().sort((a,b)=>a.date.localeCompare(b.date)).slice(-8),max=Math.max(...recent.map(m=>m.score),1),points=recent.map((m,i)=>`${i/(Math.max(recent.length-1,1))*100},${100-(m.score/max*82)}`).join(' ');chart.innerHTML=`<svg viewBox="0 0 100 100" preserveAspectRatio="none"><path d="M 0 92 H 100" stroke="#2b3543" stroke-width=".5"/><polyline points="${points}" fill="none" stroke="#d9f77a" stroke-width="2" vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-linejoin="round"/>${recent.map((m,i)=>`<circle cx="${i/(Math.max(recent.length-1,1))*100}" cy="${100-(m.score/max*82)}" r="1.8" fill="#d9f77a"/>`).join('')}</svg>`}
function renderGames(games){const grid=$('#gamesGrid');if(!games.length){grid.innerHTML='<div class="empty-state large">Aucun jeu pour le moment.<br><span>Ajoutez une partie pour commencer votre collection.</span></div>';return}grid.innerHTML=games.map(g=>{const rows=matches.filter(m=>m.game===g),best=rows.slice().sort((a,b)=>b.score-a.score)[0],wins=rows.filter(m=>m.winner==='Cédric').length;return `<article class="game-card"><h3>${g}</h3><p>${rows.length} partie${rows.length>1?'s':''} · ${wins} win${wins>1?'s':''} Cédric</p><div class="game-score">${fmt(best.score)}</div><p>record de ${best.winner}</p></article>`}).join('')}
function renderHistory(){const el=$('#historyList');if(!matches.length){el.innerHTML='<div class="empty-state large">Aucune partie enregistrée.<br><span>Le premier match lancera officiellement la rivalité.</span></div>';return}el.innerHTML=matches.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(m=>`<div class="history-item"><div class="history-game">${m.game}</div><div class="winner">${m.winner}</div><div class="score">${fmt(m.score)}</div><div class="history-date">${dateLabel(m.date)}</div><div class="win-label">WIN · ${m.winner}</div></div>`).join('')}
function openModal(){const modal=$('#modal');modal.hidden=false;const input=$('[name="game"]');$('[name="date"]').value=new Date().toISOString().slice(0,10);setTimeout(()=>input.focus(),20)}function closeModal(){$('#modal').hidden=true}
$$('[data-view-link]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();showView(el.dataset.viewLink)}));$$('[data-open-modal]').forEach(el=>el.addEventListener('click',openModal));$$('[data-close-modal]').forEach(el=>el.addEventListener('click',closeModal));$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
$('#matchForm').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));matches.push({...data,score:Number(data.score)});save();e.target.reset();closeModal();render();showView('history')});render();
